<?php require 'includes/header.php'; require 'config/db.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=$_POST['teacher_id'];$n=$_POST['name'];$p=$_POST['phone'];$e=$_POST['email'];$s=$_POST['subject'];$q=$conn->prepare("INSERT INTO teachers(teacher_id,name,phone,email,subject) VALUES(?,?,?,?,?)");$q->bind_param('sssss',$id,$n,$p,$e,$s);$q->execute();header('Location:teachers.php');exit;}
if(isset($_GET['delete'])){$conn->query("DELETE FROM teachers WHERE id=".(int)$_GET['delete']);header('Location:teachers.php');exit;}
$rows=$conn->query("SELECT * FROM teachers ORDER BY id DESC");?>
<div class="d-flex justify-content-between mb-3"><h3>Teachers</h3><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#add">+ Add Teacher</button></div>
<div class="card p-3"><table class="table"><tr><th>ID</th><th>Name</th><th>Phone</th><th>Email</th><th>Subject</th><th></th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['teacher_id']?></td><td><?=$r['name']?></td><td><?=$r['phone']?></td><td><?=$r['email']?></td><td><?=$r['subject']?></td><td><a class="btn btn-sm btn-danger" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></table></div>
<div class="modal fade" id="add"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5>Add Teacher</h5></div><div class="modal-body">
<input class="form-control mb-2" name="teacher_id" placeholder="Teacher ID" required><input class="form-control mb-2" name="name" placeholder="Full name" required><input class="form-control mb-2" name="phone" placeholder="Phone"><input class="form-control mb-2" name="email" placeholder="Email"><input class="form-control" name="subject" placeholder="Subject"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div><?php require 'includes/footer.php'; ?>